input.old_string:
.type-display {
  font-family: var(--font-display), ui-sans-serif, system-ui, sans-serif;
  font-size: 2.25rem;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

@media (min-width: 640px) {
  .type-display {
    font-size: 2.5rem;
  }
}

input.new_string:
.type-display {
  font-family: var(--font-display), ui-sans-serif, system-ui, sans-serif;
  font-size: 2rem;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

@media (min-width: 640px) {
  .type-display {
    font-size: 2.25rem;
  }
}

%{
  value: amount,
  option: option,
  id: amount_option_id(amount),
  formatted: DonationPresenter.format_idr(amount)
}

  class={
    amount_option_classes(selected_amount_option == preset.option)
  }
>
  <input
    id={preset.id}
    type="radio"
    name={@form[:amount_option].name}
    value={preset.value}
    checked={selected_amount_option == preset.option}
    class="sr-only"
  />

  <span class="type-amount-md">
    Rp {preset.formatted}
  </span>
</label>

<label
  for="donation_form_amount_option_custom"
  class={amount_option_classes(selected_amount_option == "custom")}
>
